## Why This Is Asked
This question tests system design for risk-critical prompts, ensemble routing, privacy, latency budgets, and auditing.

## Key Concepts
- Prompt orchestration
- Ensemble voting and tie-breaks
- Privacy-preserving logging
- Latency budgeting and degradation
- API design and data models

## Code Example

```python
# Minimal prototype showing routing decisions
class Module:
    def __call__(self, prompt, context):
        return {"output": f"Result from {self.__class__.__name__}", "score": 0.9}

class RiskAnalyst(Module):
    pass
class ComplianceCheck(Module):
    pass
class ExplainabilityLogger(Module):
    pass

def redact(s):
    return "***REDACTED***" if isinstance(s, str) else s

def vote(outputs):
    tally = {}
    for o in outputs:
        key = o.get("origin")
        tally[key] = tally.get(key, 0) + 1
    max_key = max(tally, key=tally.get)
    if tally[max_key] >= 2:
        for o in outputs:
            if o.get("origin") == max_key:
                return o
    return outputs[0]

def route(prompt, context):
    rm = RiskAnalyst()
    cm = ComplianceCheck()
    em = ExplainabilityLogger()
    redacted_context = {k: redact(v) for k, v in context.items()}
    a = rm(prompt, redacted_context)
    b = cm(prompt, redacted_context)
    c = em(prompt, redacted_context)
    chosen = vote([a, b, c])
    return {"final": chosen, "logs": [a, b, c], "audit": redacted_context}
```

## Why This Is Asked
This question evaluates the ability to design monitoring systems for prompt evolution under ABAC-like tenant policies and safety drift scenarios.

## Key Concepts
- Prompt drift detection using embeddings and cosine similarity
- Per-tenant policies with ABAC-like guardrails
- Latency-aware monitoring with configurable drift thresholds
- Explainable guardrail recommendations

## Code Example
```python
import numpy as np
from typing import List, Dict, Tuple

class MockEncoder:
    def encode(self, text: str) -> np.ndarray:
        codes = np.array([ord(c) for c in text[:50]])
        return codes / (np.linalg.norm(codes) + 1e-8)

    def classify_safety(self, text: str) -> float:
        risk_keywords = ["hack", "exploit", "bypass", "injection"]
        return min(1.0, sum(1 for k in risk_keywords if k in text.lower()) * 0.3)

class PromptDriftDetector:
    def __init__(self, encoder: MockEncoder, drift_threshold: float = 0.8):
        self.encoder = encoder
        self.drift_threshold = drift_threshold
        self.tenant_prompts: Dict[str, Dict[str, np.ndarray]] = {}

    def register_prompt(self, tenant_id: str, model_version: str, prompt: str):
        if tenant_id not in self.tenant_prompts:
            self.tenant_prompts[tenant_id] = {}
        self.tenant_prompts[tenant_id][model_version] = self.encoder.encode(prompt)

    def detect_drift(self, tenant_id: str, old_version: str, new_version: str, prompt: str) -> Dict:
        if tenant_id not in self.tenant_prompts:
            return {"drift_detected": False, "risk_score": 0.0}
        old_vec = self.tenant_prompts[tenant_id].get(old_version)
        new_vec = self.encoder.encode(prompt)
        similarity = np.dot(old_vec, new_vec) if old_vec is not None else 1.0
        risk_score = self.encoder.classify_safety(prompt)
        return {
            "drift_detected": similarity < self.drift_threshold,
            "similarity": float(similarity),
            "risk_score": risk_score,
            "guardrails": self._generate_guardrails(risk_score)
        }

    def _generate_guardrails(self, risk_score: float) -> List[str]:
        if risk_score > 0.7:
            return ["Enable content filtering", "Require human review", "Block high-risk prompts"]
        elif risk_score > 0.3:
            return ["Log for auditing", "Apply soft filtering"]
        return ["Standard monitoring"]

# Usage
detector = PromptDriftDetector(MockEncoder(), drift_threshold=0.8)
detector.register_prompt("tenant_1", "v1.0", "Write a function to sort a list")
result = detector.detect_drift("tenant_1", "v1.0", "v1.1", "How to hack into a system")
print(result)
```

## Why This Is Asked
Tests architecture for intent resolution, safe routing, and token budgeting under real-world noise.

## Key Concepts
- Intent detection and confidence thresholds
- Template routing to data-extraction, summarization, code-generation
- Safety guards to prevent system-prompt leakage
- Token budgeting and edge-case handling

## Code Example
```typescript
type Template = 'data-extraction'|'summarization'|'code-generation';
type Payload = { template: Template; tokenBudget: number; justification: string; };
function routePrompt(prompt: string, signals: {intent?: string; confidence?: number;}): Payload {
  const t = (signals.intent === 'summarize' && (signals.confidence ?? 0) > 0.8) ? 'summarization'
            : (signals.intent === 'extract' && (signals.confidence ?? 0) > 0.8) ? 'data-extraction'
            : (signals.intent === 'generate' && (signals.confidence ?? 0) > 0.8) ? 'code-generation'
            : 'summarization';
  const budgets: Record<Template, number> = {'data-extraction': 800, 'summarization': 500, 'code-generation': 1200};
  return { template: t, tokenBudget: budgets[t], justification: 'inferred from signals with fallback' };
}
```

